customCSS:
.t, .history { color: #525252; }
.join { color: #25be6a; }
.part, .quit { color: #525252; }
.kick, .error { color: #ee5396; }
.notice { color: #08bdba; }
.action { color: #be95ff; }
.mode, .nick, .topic, .server { color: #33b1ff; }
.highlight { color: #f2f4f8; background-color: #2a2a2a; border-left: 3px solid #be95ff; padding-left: 8px; }
.reply { color: #525252; border-left: 2px solid #78a9ff; padding-left: 6px; }
.oper { color: #161616; background-color: #08bdba; }
.reactions { color: #78a9ff; background-color: #282828; }
.card { background-color: #282828; border-color: #525252; }
.card-title { color: #78a9ff; }
.card-desc { color: #525252; }
.daychange { color: #525252; border-color: #282828; }
